CREATE TABLE `loyalty_rules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `type` ENUM('POINTS', 'CASHBACK') NOT NULL, `active` BOOLEAN NOT NULL DEFAULT false, `earn_rate` INT UNSIGNED NOT NULL, `min_eligible_amount_cents` BIGINT UNSIGNED NOT NULL DEFAULT 0, `redeem_rate_cents_per_point` INT UNSIGNED NULL, `expiration_days` SMALLINT UNSIGNED NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `loyalty_rules_public_id_key` (`public_id`), UNIQUE INDEX `loyalty_rules_tenant_id_type_key` (`tenant_id`, `type`), CONSTRAINT `loyalty_rules_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `loyalty_ledger_entries` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `customer_id` BIGINT UNSIGNED NOT NULL, `type` ENUM('POINTS', 'CASHBACK') NOT NULL, `direction` ENUM('CREDIT', 'DEBIT') NOT NULL, `reason` ENUM('EARNED', 'REDEEMED', 'EXPIRED', 'REVERSED') NOT NULL, `amount` BIGINT UNSIGNED NOT NULL, `discount_cents_applied` BIGINT UNSIGNED NULL, `source_payment_id` BIGINT UNSIGNED NULL, `source_appointment_id` BIGINT UNSIGNED NULL, `related_entry_id` BIGINT UNSIGNED NULL, `expires_at` DATETIME(3) NULL, `user_id` BIGINT UNSIGNED NULL, `session_id` BIGINT UNSIGNED NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `loyalty_ledger_entries_public_id_key` (`public_id`), UNIQUE INDEX `loyalty_ledger_entries_related_entry_id_key` (`related_entry_id`), UNIQUE INDEX `loyalty_ledger_entries_tenant_type_payment_direction_key` (`tenant_id`, `type`, `source_payment_id`, `direction`), INDEX `loyalty_ledger_entries_tenant_id_customer_id_type_idx` (`tenant_id`, `customer_id`, `type`), INDEX `loyalty_ledger_entries_tenant_id_type_expires_at_idx` (`tenant_id`, `type`, `expires_at`), INDEX `loyalty_ledger_entries_tenant_id_source_appointment_id_idx` (`tenant_id`, `source_appointment_id`), CONSTRAINT `loyalty_ledger_entries_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_source_payment_id_fkey` FOREIGN KEY (`source_payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_source_appointment_id_fkey` FOREIGN KEY (`source_appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_related_entry_id_fkey` FOREIGN KEY (`related_entry_id`) REFERENCES `loyalty_ledger_entries`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `loyalty_ledger_entries_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
